import{_ as e,c as o,a2 as t,o as l}from"./chunks/framework.GMKO7RMU.js";const b=JSON.parse('{"title":"使用身份验证器（Authenticator）开启 Facebook 双重验证（2FA）可以极大地提升账号安全性，防止因密码泄露导致的盗号。","description":"","frontmatter":{"title":"使用身份验证器（Authenticator）开启 Facebook 双重验证（2FA）可以极大地提升账号安全性，防止因密码泄露导致的盗号。"},"headers":[],"relativePath":"KnowledgeBase/一些工具/Authenticatorfor2FA.md","filePath":"KnowledgeBase/一些工具/Authenticatorfor2FA.md","lastUpdated":1777096888000}'),i={name:"KnowledgeBase/一些工具/Authenticatorfor2FA.md"};function r(c,a,n,s,h,u){return l(),o("div",null,a[0]||(a[0]=[t('<p>使用身份验证器（Authenticator）开启 Facebook 双重验证（2FA）可以极大地提升账号安全性，防止因密码泄露导致的盗号。</p><h2 id="第一步-准备身份验证器应用" tabindex="-1">第一步：准备身份验证器应用 <a class="header-anchor" href="#第一步-准备身份验证器应用" aria-label="Permalink to &quot;第一步：准备身份验证器应用&quot;">​</a></h2><p>在手机应用商店下载并安装一个身份验证器。推荐使用：</p><ul><li>Google Authenticator（谷歌验证器）</li><li>Microsoft Authenticator（微软验证器）</li></ul><h2 id="第二步-在-facebook-中开启设置" tabindex="-1">第二步：在 Facebook 中开启设置 <a class="header-anchor" href="#第二步-在-facebook-中开启设置" aria-label="Permalink to &quot;第二步：在 Facebook 中开启设置&quot;">​</a></h2><ol><li>进入设置：打开 Facebook，点击头像，进入 <a href="https://www.facebook.com/settings" target="_blank" rel="noreferrer">设置与隐私</a> -&gt; 设置。</li><li>进入账号中心：在左侧或顶部菜单点击 账号中心 (Accounts Center)。</li><li>找到安全选项：点击 密码和安全 (Password and security) -&gt; 双重验证 (Two-factor authentication)。</li><li>选择账号：选择你需要设置的 Facebook 个人账号。</li></ol><h2 id="第三步-绑定验证器" tabindex="-1">第三步：绑定验证器 <a class="header-anchor" href="#第三步-绑定验证器" aria-label="Permalink to &quot;第三步：绑定验证器&quot;">​</a></h2><ol><li>选择验证方式：在弹出的选项中，选择 验证应用 (Authentication app)。</li><li>获取密钥/二维码：Facebook 会显示一个二维码或一串字符密钥。</li><li>在验证器中添加：</li></ol><ul><li>打开手机上的 Authenticator 应用，点击 “+” 号。 <ul><li>选择 扫描二维码（直接扫 Facebook 屏幕上的码）或 手动输入密钥（将 Facebook 提供的字符复制进去）。</li></ul></li></ul><ol start="4"><li>确认绑定：验证器应用会立即生成一个 6 位数字动态码。回到 Facebook 页面，输入这个动态码完成确认。</li></ol><h2 id="关键注意事项" tabindex="-1">关键注意事项 <a class="header-anchor" href="#关键注意事项" aria-label="Permalink to &quot;关键注意事项&quot;">​</a></h2><ul><li>备份恢复码：设置完成后，Facebook 会提供一组公共恢复码 (Recovery Codes)。请务必将它们截图或抄写下来存放在安全的地方。如果手机丢失或应用被删，这是你找回账号的唯一途径。</li><li>跨设备登录：开启后，每当在陌生浏览器或新设备登录时，除了密码，你都必须输入验证器内生成的最新 6 位码。</li></ul>',12)]))}const f=e(i,[["render",r]]);export{b as __pageData,f as default};
